case class TodoState(items: List[Todo])
val handler = new ActionHandler(zoomTo(_.items)) {
  override def handle = {
    case Add(text) => updated(value :+ Todo(text))
    case Done(id)  => updated(value.map(i => if (i.id == id) i.copy(done = true) else i))
  }
}
val circuit = Circuit[TodoState](TodoState(Nil), composeHandlers(handler))
